def collect_inflight_reqs(self) -> Set[Req]:
    return {
        req
        for batch in self._collect_inflight_batches()
        if batch is not None
        for req in batch.reqs
    }

_collect_inflight_batches.source:
def _collect_inflight_batches(self) -> list[ScheduleBatch | None]:
    if get_parallel().pp_size == 1:
        inflight_batches = [self.running_batch, self.last_batch]
    else:
        inflight_batches = [*self.running_mbs, *self.mbs]
    if self.enable_continuous_input_polling and self.result_queue:
        # Polling can run intake before the newest queued batch becomes last_batch.
        inflight_batches.extend(batch for batch, _ in self.result_queue)
    return inflight_batches

_get_running_request_total_token_offset.source:
def _get_running_request_total_token_offset(self, req: Req) -> int:
    # Fixed-length requests cannot benefit from the early-EOS estimate.
    ratio = 1.0 if req.sampling_params.ignore_eos else self.new_token_ratio
    return (
        min(
            (req.sampling_params.max_new_tokens - len(req.output_ids)),
            CLIP_MAX_NEW_TOKENS,
        )
        * ratio
    )

NewTokenRatioTracker.source:
@dataclass(slots=True, kw_only=True)
class NewTokenRatioTracker:
    init: float
    min: float
    decay: float
    current: float

    @classmethod
    def from_config(cls) -> NewTokenRatioTracker:
        init = min(
            envs.SGLANG_INIT_NEW_TOKEN_RATIO.get()
            * get_schedule().schedule_conservativeness,
            1.0,
        )
        min_ratio = min(
            init * envs.SGLANG_MIN_NEW_TOKEN_RATIO_FACTOR.get(),
            1.0,
        )
        decay = (init - min_ratio) / envs.SGLANG_NEW_TOKEN_RATIO_DECAY_STEPS.get()
        return cls(init=init, min=min_ratio, decay=decay, current=init)

    def decay_step(self) -> None:
        self.current = max(self.current - self.decay, self.min)

    def reset(self) -> None:
        self.current = self.init

    @staticmethod
    def estimate_new_token_ratio_after_retract(reqs: Sequence[Req]) -> float:
        total_decoded_tokens = sum(len(r.output_ids) for r in reqs)
        total_max_new_tokens = sum(r.sampling_params.max_new_tokens for r in reqs)

        new_estimate_ratio = (
            total_decoded_tokens + envs.SGLANG_RETRACT_DECODE_STEPS.get() * len(reqs)
        ) / (total_max_new_tokens + 1)  # avoid zero division
        new_estimate_ratio = min(1.0, new_estimate_ratio)
        return new_estimate_ratio

PrefillBudget.source:
class PrefillBudget:
    """Fixed token pool. Offsets include pending allocations and decode headroom."""

    # When False, admission skips the FULL spec and passes the host hit length.
    load_back_needs_full_tokens = False

    def __init__(self, allocator, tree_cache, *, num_mixed_decode_tokens: int = 0):
        self.allocator = allocator
        self.tree_cache = tree_cache
        self.page_size = allocator.page_size
        self.total_offset = num_mixed_decode_tokens
        self.current_offset = num_mixed_decode_tokens
        self.swa_offset = 0

    def ceil_paged_tokens(self, tokens: int) -> int:
        return -(-tokens // self.page_size) * self.page_size

    def prepare_load_back(
        self,
        *,
        full_tokens: int,
        extend_input_len: int,
        max_new_tokens: int,
        swa_host_hit_length: int,
        chunk_limit: int | None,
    ) -> bool:
        """Prepare pools whose admission depends on movable shared space."""
        return True

    def _available_and_evictable(self):
        evictable = (
            self.tree_cache.full_evictable_size()
            if self.tree_cache.supports_mamba()
            else self.tree_cache.evictable_size()
        )
        return self.allocator.available_size() + evictable

    @property
    def remaining_total(self):
        return self._available_and_evictable() - self.total_offset

    @property
    def remaining_current(self):
        return self._available_and_evictable() - self.current_offset

    @property
    def remaining_swa(self):
        return 0

    def has_capacity(self) -> bool:
        return self.remaining_total > 0 and self.remaining_current > 0

    def check_prefill(
        self,
        *,
        extend_input_len: int,
        total_tokens: int,
        max_new_tokens: int,
        input_tokens: int,
        swa_host_hit_length: int,
        chunk_limit: int | None,
        auxiliary_swa_host_hit_length: int = 0,
    ) -> tuple[bool, int | None]:
        """Return admission feasibility and a memory bound on the requested chunk."""
        return (
            (True, chunk_limit)
            if total_tokens < self.remaining_total
            else (False, None)
        )

    def can_allocate_prefill(
        self,
        *,
        paged_input: int,
        extend_input_len: int,
        max_new_tokens: int,
        chunk_limit: int | None,
    ) -> bool:
        return paged_input <= min(self.remaining_current, self.remaining_total)

    def available_chunk_tokens(self, chunk_limit: int) -> int | None:
        available = min(chunk_limit, int(self.remaining_total))
        # Single-pool continuation must make progress to release its KV.
        return available if available > 0 else chunk_limit

    def fit_chunk(
        self,
        *,
        extend_input_len: int,
        max_new_tokens: int,
        chunk_limit: int,
    ) -> int | None:
        return chunk_limit

    def reserve(
        self,
        extend_input_len: int,
        max_new_tokens: int,
        *,
        extra_tokens: int = 0,
        chunk_limit: int | None = None,
        is_chunked_continuation: bool = False,
    ) -> None:
        extend_input_len = self.ceil_paged_tokens(extend_input_len)
        immediate = extend_input_len + self.page_size + extra_tokens
        self.total_offset += immediate + max_new_tokens
        self.current_offset += immediate

insert.source:
@rank_consensus(
    same_params=["len(params.key)"],
    same_results=["result.prefix_len"],
)
def insert(self, params: InsertParams) -> InsertResult:
    if self.disable:
        return InsertResult(prefix_len=0)
    # Fail fast on re-entrancy without touching the in-flight walk.
    assert not self.tree_core.has_ongoing_insert(), "re-entrant insert"
    if self.buffer_pipeline is not None:
        self.buffer_pipeline.begin_insert_walk()
    # Pump the resumable insert, applying each step's actions at its barrier.
    try:
        step = self.tree_core.begin_insert(params)
        while True:
            self._apply_cache_actions(step.actions)
            if step.result is not None:
                # Walk actions flow through the steps; the result is action-free.
                assert not step.result.cache_actions
                return step.result
            step = self.tree_core.resume_insert()
    finally:
        # Drain still-pending actions so frees reach the allocator on abort.
        self._apply_cache_actions(self.tree_core.end_insert())
        if self.buffer_pipeline is not None:
            self.buffer_pipeline.end_insert_walk()

_apply_cache_actions.source:
def _apply_cache_actions(
    self, actions: list[CacheAction | ComponentAction]
) -> None:
    # Apply and consume one at a time: a spent list cannot be double-applied.
    actions.reverse()
    try:
        while actions:
            self._apply_cache_action(actions.pop())
    finally:
        actions.reverse()

_apply_cache_action.source:
def _apply_cache_action(self, action: CacheAction | ComponentAction) -> None:
    # Component actions route to their component class; the rest are
    # cache-owned and handled here by type.
    if isinstance(action, ComponentAction):
        if (
            isinstance(action, UpdatePendingBackupOnNodeSplit)
            and action.ack_id is not None
        ):
            node_ids = [action.new_node_id, action.new_child_node_id]
            self._replace_pending_write_through_node(
                action.ack_id, action.old_node_id, node_ids
            )
            if self.linker is not None:
                self.linker.replace_pending_offload_node(
                    action.ack_id, action.old_node_id, node_ids
                )
        self.components[action.component_type].apply_component_action(action)
    elif isinstance(action, FreeDeviceKV):
        # tree values are page-aligned copies of a kv row: page-exact segments
        for indices in action.indices:
            self.token_to_kv_pool_allocator.free_segment(indices, start_pos=0)
    elif isinstance(action, FreeDeviceKVFullOnly):
        for indices in action.indices:
            self.token_to_kv_pool_allocator.free_full_segment(indices, start_pos=0)
    elif isinstance(action, BackupKV):
        if self.linker is not None:
            self.linker.offload_nodes(action.node_ids)
        else:
            self._execute_and_commit_kv_backup(action)
    else:
        raise AssertionError(f"unhandled CacheAction: {type(action).__name__}")

_execute_kv_backup.source:
def _execute_kv_backup(self, node_id, device_value, comp_xfers, sidecar_xfers):
    """Execute Backup action."""
    kv_tokens = len(device_value)
    anchor_entry = self.cache_controller.mem_pool_host.anchor_entry
    if (
        anchor_entry.host_pool.shared_allocation_domain is None
        or anchor_entry.host_evict_fn is None
    ):
        host_avail = self.cache_controller.mem_pool_host.available_size()
        if host_avail < kv_tokens:
            needed = kv_tokens - host_avail
            if self.evict_host(needed) < needed:
                return None
    aux_xfers = [x for xfers in comp_xfers.values() for x in xfers]
    aux_xfers.extend(sidecar_xfers)
    # Defer submission so the next flush can merge pending node backups.
    return self.cache_controller.write(
        device_value, node_id=node_id, extra_pools=aux_xfers or None, flush=False
    )
